fn urlencode(text: &str, extra_safe: &[u8]) -> String {
    let mut out = String::new();
    for byte in text.as_bytes() {
        let c = *byte;
        let safe = c.is_ascii_alphanumeric()
            || matches!(c, b'-' | b'_' | b'.' | b'~')
            || extra_safe.contains(&c);
        if safe {
            out.push(c as char);
        } else {
            out.push_str(&format!("%{c:02X}"));
        }
    }
    out
